$config=require($argv[1]??'');if(isset($config['database'])&&is_array($config['database']))$config=$config['database'];$database=$config['db']??($config['name']??null);if($database!==EXPECTED_DATABASE)throw new RuntimeException('Unexpected database');$sqlPath=$argv[2]??'';if(!is_file($sqlPath))throw new RuntimeException('Phase 87 SQL missing');
$pdo=new PDO('mysql:host='.$config['host'].';port='.($config['port']??3306).';dbname='.$database.';charset=utf8mb4',$config['user'],$config['pass']??$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::MYSQL_ATTR_MULTI_STATEMENTS=>true,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$s=$pdo->prepare(file_get_contents($sqlPath));$s->execute();do{if($s->columnCount())$s->fetchAll();}while($s->nextRowset());$s->closeCursor();
$outcomes=$pdo->query("SELECT o.agent_key,o.nct_id,o.outcome_index,o.title,o.description,o.time_frame,t.source_url,COUNT(m.measurement_index) measurement_count FROM ilb_psoriasis_aggregate_outcome o JOIN ilb_psoriasis_aggregate_trial t ON t.agent_key=o.agent_key AND t.nct_id=o.nct_id LEFT JOIN ilb_psoriasis_aggregate_measurement m ON m.agent_key=o.agent_key AND m.nct_id=o.nct_id AND m.outcome_index=o.outcome_index WHERE o.outcome_class='WITHDRAWAL_RELAPSE' GROUP BY o.agent_key,o.nct_id,o.outcome_index,o.title,o.description,o.time_frame,t.source_url ORDER BY o.agent_key,o.nct_id,o.outcome_index")->fetchAll();if(!$outcomes)throw new RuntimeException('No withdrawal outcomes available');
$pdo->beginTransaction();try{$pdo->exec('DELETE FROM ilb_psoriasis_withdrawal_identifiability');$i=$pdo->prepare('INSERT INTO ilb_psoriasis_withdrawal_identifiability(agent_key,nct_id,outcome_index,outcome_title,time_frame,measurement_count,candidate_R,candidate_E,candidate_F,candidate_L,identifies_persistence_state,decision,computation_eligible,source_url) VALUES(?,?,?,?,?,?,?,?,?,?,0,?,0,?)');foreach($outcomes as $o){$v=$o['title'].' '.($o['description']??'');$r=preg_match('/resident.?memory|\bTRM\b|tissue.?resident|\bCD4\b|\bCD8\b|T.?cell/i',$v)?1:0;$e=preg_match('/keratinocyte|epigen|chromatin|transcript|gene.?expression/i',$v)?1:0;$f=preg_match('/fibroblast|stromal/i',$v)?1:0;$l=preg_match('/microbi|infection|barrier|injur|stress|trigger|antigen/i',$v)?1:0;$decision=($r+$e+$f+$l)>0?'STATE_CANDIDATE_TEXT':'CLINICAL_RELAPSE_ONLY';$i->execute([$o['agent_key'],$o['nct_id'],$o['outcome_index'],$o['title'],$o['time_frame'],$o['measurement_count'],$r,$e,$f,$l,$decision,$o['source_url']]);}$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
$counts=$pdo->query('SELECT decision,COUNT(*) outcome_count,SUM(measurement_count) measurement_count FROM ilb_psoriasis_withdrawal_identifiability GROUP BY decision ORDER BY decision')->fetchAll();$states=$pdo->query('SELECT SUM(candidate_R) R_text_candidates,SUM(candidate_E) E_text_candidates,SUM(candidate_F) F_text_candidates,SUM(candidate_L) L_text_candidates,SUM(identifies_persistence_state) identified_states FROM ilb_psoriasis_withdrawal_identifiability')->fetch();$samples=$pdo->query("SELECT agent_key,nct_id,outcome_title,time_frame,decision,source_url FROM ilb_psoriasis_withdrawal_identifiability WHERE decision='STATE_CANDIDATE_TEXT' ORDER BY nct_id LIMIT 50")->fetchAll();$identified=(int)$states['identified_states'];if($identified!==0)throw new RuntimeException('Text candidates were incorrectly promoted to identified mechanisms');
